import z3

n = 7
# Create integer variables x[i][j] in [0,6]
x = [[z3.Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]

s = z3.Solver()

# Domain constraints
for i in range(n):
    for j in range(n):
        s.add(x[i][j] >= 0, x[i][j] <= n-1)

# Latin square: each row is a permutation
for i in range(n):
    s.add(z3.Distinct([x[i][j] for j in range(n)]))

# Each column is a permutation
for j in range(n):
    s.add(z3.Distinct([x[i][j] for i in range(n)]))

# Idempotent diagonal
for i in range(n):
    s.add(x[i][i] == i)

# QG3: x[x[i][j]][x[j][i]] = i
# This is tricky: we need to index by values of x.
# We can use an element constraint or encode with if-then-else.

# For each i, j, we need: for all a, b in [0,6], if x[i][j]==a and x[j][i]==b then x[a][b]==i
# This can be encoded as: And([Implies(And(x[i][j]==a, x[j][i]==b), x[a][b]==i) for a in range(n) for b in range(n)])
# But that's n^2 * n^2 = 2401 implications. Let's try.

for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                s.add(z3.Implies(z3.And(x[i][j] == a, x[j][i] == b), x[a][b] == i))

print("Solving...")
result = s.check()
print("Result:", result)
if result == z3.sat:
    m = s.model()
    grid = [[m.evaluate(x[i][j]).as_long() for j in range(n)] for i in range(n)]
    print("Solution:")
    for row in grid:
        print(row)
    # Verify
    flat = []
    for i in range(n):
        for j in range(n):
            flat.append(grid[i][j])
    print("Flat:", flat)
else:
    print("UNSAT")

