# For n=3, enumerate all Latin squares? That's 12 Latin squares of order 3.
# Let's just brute force all assignments (9 cells, each 0-2) but that's 3^9 = 19683, manageable.

n = 3
count = 0
for flat in itertools.product(range(n), repeat=n*n):
    grid = [list(flat[i*n:(i+1)*n]) for i in range(n)]
    if is_latin(grid, n) and is_idempotent(grid, n) and check_qg3(grid, n):
        print("Found solution for n=3:")
        for row in grid:
            print(row)
        count += 1
print(f"Total solutions for n=3: {count}")

