import itertools

def check_qg3(grid, n):
    for i in range(n):
        for j in range(n):
            a = grid[i][j]
            b = grid[j][i]
            if grid[a][b] != i:
                return False
    return True

def is_latin(grid, n):
    for i in range(n):
        if sorted(grid[i]) != list(range(n)):
            return False
    for j in range(n):
        if sorted([grid[i][j] for i in range(n)]) != list(range(n)):
            return False
    return True

def is_idempotent(grid, n):
    for i in range(n):
        if grid[i][i] != i:
            return False
    return True

# Generate all Latin squares of order 4 with idempotent diagonal
# We can use the fact that the first row (after diagonal) determines a lot
# But let's just use a backtracking search

n = 4
solutions = []

def backtrack(grid, i, j):
    if i == n:
        if check_qg3(grid, n):
            solutions.append([row[:] for row in grid])
        return
    if j == n:
        backtrack(grid, i+1, 0)
        return

    # Determine possible values
    used_row = set(grid[i][:j])
    used_col = set(grid[k][j] for k in range(i))

    for v in range(n):
        if v in used_row or v in used_col:
            continue
        if i == j and v != i:
            continue
        grid[i][j] = v
        backtrack(grid, i, j+1)

grid = [[-1]*n for _ in range(n)]
backtrack(grid, 0, 0)
print(f"Total solutions for n=4: {len(solutions)}")
for sol in solutions:
    for row in sol:
        print(row)
    print()
